package com.example.examplemod.cargo.center;

import com.example.examplemod.cargo.*;
import com.example.examplemod.economy.EconomyManager;
import net.minecraft.nbt.*;
import net.minecraft.server.MinecraftServer;
import net.minecraft.server.level.ServerPlayer;
import net.minecraft.world.item.ItemStack;
import net.neoforged.bus.api.SubscribeEvent;
import net.neoforged.fml.common.EventBusSubscriber;
import net.neoforged.neoforge.event.tick.ServerTickEvent;
import java.nio.charset.StandardCharsets;
import java.util.*;

/** Quote -> escrow -> single native request -> observed physical receipt -> idempotent settlement. */
@EventBusSubscriber(modid="createcityexpansioncore")
public final class CargoFulfillment {
    private record Prepared(UUID token,long expires,OwnerRef payer,OwnerRef seller,UUID offer,
                            CargoWarehouseRegistry.Warehouse source,CargoWarehouseRegistry.Warehouse destination,
                            ItemStack item,int quantity,long goods,CargoRoutePlanner.Route route,List<CargoCommerceBook.Fee> fees) {}
    private static final Map<ServerPlayer,Prepared> QUOTES=new WeakHashMap<>();
    private CargoFulfillment() {}
    public static String stockKey(MinecraftServer s,ItemStack type){return UUID.nameUUIDFromBytes(type.copyWithCount(1).save(s.registryAccess()).toString().getBytes(StandardCharsets.UTF_8)).toString();}
    public static ItemStack stockChoice(ServerPlayer actor,CargoWarehouseRegistry.Warehouse warehouse,String token){var ticker=CargoWarehouseRegistry.ticker(actor.getServer(),warehouse);if(ticker==null)throw new IllegalArgumentException("delivery_source_unavailable");return ticker.warehouseStock(actor,warehouse.id()).orElseThrow().stream().map(CargoTickerBlockEntity.StockEntry::type).filter(item->stockKey(actor.getServer(),item).equals(token)).findFirst().orElseThrow();}
    private static Prepared prepare(ServerPlayer actor,UUID selected,boolean purchase,CompoundTag values){
        var s=actor.getServer();var registry=CargoWarehouseRegistry.get(s);var book=EconomyManager.get(actor.serverLevel()).cargo();
        var payer=CenterOperations.owner(values.getString("Owner"));if(!payer.canSpend(s,actor.getUUID()))throw new IllegalArgumentException("delivery_payer_denied");
        var offer=purchase?book.offer(selected).orElseThrow():null;var source=registry.find(purchase?offer.warehouse():selected).orElseThrow();var destination=registry.find(CenterOperations.id(values,"Destination")).orElseThrow();
        if(!CargoWarehouseRegistry.access(s,destination).owner().operates(s,actor.getUUID())||CargoWarehouseRegistry.receivingInventory(s,destination)==null)throw new IllegalArgumentException("delivery_receiver_unavailable");
        OwnerRef seller=CargoWarehouseRegistry.access(s,source).owner();ItemStack item;
        int quantity=Math.toIntExact(CenterOperations.number(values,"Quantity"));if(quantity<1||quantity>4096)throw new IllegalArgumentException("delivery_quantity_invalid");
        if(purchase){if(!offer.active()||quantity>offer.remaining()||!offer.owner().equals(seller))throw new IllegalArgumentException("delivery_offer_changed");var access=CargoOwners.get(s).access("offer/"+offer.id(),offer.creator(),CargoTrainRegistry.AccessMode.PUBLIC);if(!CargoOwners.permits(s,OwnerRef.player(actor.getUUID()),access))throw new IllegalArgumentException("delivery_offer_denied");item=ItemStack.parseOptional(s.registryAccess(),offer.item());}
        else {var sourceOwner=CargoWarehouseRegistry.access(s,source).owner();if(sourceOwner.kind()==OwnerRef.Kind.COMPANY?!EconomyManager.get(actor.serverLevel()).companies().permits(sourceOwner.id(),actor.getUUID(),com.example.examplemod.economy.company.CompanyBook.Permission.TRADE):!sourceOwner.manages(s,actor.getUUID()))throw new IllegalArgumentException("delivery_source_denied");if(!CargoWarehouseRegistry.permits(actor,source))throw new IllegalArgumentException("delivery_source_denied");item=stockChoice(actor,source,values.getString("Stock"));}
        if(item.isEmpty())throw new IllegalArgumentException("delivery_stock_unavailable");
        if(available(s,source,item)<quantity)throw new IllegalArgumentException("delivery_stock_unavailable");
        var route=CargoRoutePlanner.plan(s,payer,source.point(),destination.point(),CargoRoutePlanner.Preference.valueOf(values.getString("Preference")),values.contains("Service")?values.getString("Service"):"ANY",quantity,item).orElseThrow(()->new IllegalArgumentException("delivery_route_unavailable"));
        var fees=fees(s,route);
        return new Prepared(UUID.randomUUID(),actor.serverLevel().getGameTime()+1200,payer,seller,purchase?offer.id():null,source,destination,item,quantity,purchase?Math.multiplyExact(offer.unitPrice(),quantity):0,route,List.copyOf(fees));
    }
    public static CompoundTag quote(ServerPlayer actor,UUID selected,boolean purchase,CompoundTag values){Prepared p;try{p=prepare(actor,selected,purchase,values);}catch(IllegalArgumentException|NoSuchElementException|ArithmeticException invalid){QUOTES.remove(actor);return blockedQuote(actor,selected,purchase,values,Objects.toString(invalid.getMessage(),"delivery_route_unavailable"));}QUOTES.put(actor,p);if(p.route().trip().getBoolean("Fleet"))return fleetQuote(actor,p,values);var t=new CompoundTag();t.putUUID("Token",p.token());t.putLong("Goods",p.goods());t.putLong("Transport",p.route().price());t.putLong("Total",Math.addExact(p.goods(),p.route().price()));t.putString("Source",p.source().name());t.putString("Destination",p.destination().name());t.putInt("Quantity",p.quantity());var route=new ListTag();for(var leg:p.route().legs()){var line=CargoLineRegistry.get(actor.getServer()).find(leg.line()).orElseThrow();var v=new CompoundTag();v.putString("Name",line.name());v.putLong("Price",leg.tariff());v.putString("Carrier",CargoLineRegistry.access(actor.getServer(),line).owner().name(actor.getServer()));v.putString("Terms",line.terms());route.add(v);}t.put("Route",route);var mapRequest=new CompoundTag();var routeValues=new CompoundTag();routeValues.putString("SourcePoint",p.source().point().toString());routeValues.putString("DestinationPoint",p.destination().point().toString());routeValues.putString("Preference",values.getString("Preference"));routeValues.putString("Service",values.contains("Service")?values.getString("Service"):"ANY");mapRequest.put("MapRoute",routeValues);var points=new ListTag();for(UUID id:List.of(p.source().point(),p.destination().point())){var point=new CompoundTag();point.putString("Value",id.toString());points.add(point);}t.put("MapPreview",CargoMapView.snapshot(actor,mapRequest,points));t.put("MapValues",routeValues);t.putLong("CarrierCost",p.route().price());t.putLong("Tolls",0);var checks=new ListTag();for(String code:List.of("permissions","stock","receiver","rail","train"))check(checks,code,"READY","");check(checks,"funds",EconomyManager.get(actor.serverLevel()).accounts().balance(p.payer())>=t.getLong("Total")?"READY":"BLOCKED","delivery_payer_denied");if(p.route().trip().getBoolean("RegularEtaUnknown"))check(checks,"regular_eta_unknown","WARNING","");t.put("Checks",checks);return t;}
    public static void confirm(ServerPlayer actor,CompoundTag request,boolean purchase){
        EconomyManager.get(actor.serverLevel()).roadTolls().captureLegacy(EconomyManager.get(actor.serverLevel()).cargo().orders());UUID orderId=UUID.nameUUIDFromBytes((actor.getUUID()+"/"+request.getUUID("Request")).getBytes(StandardCharsets.UTF_8));var book=EconomyManager.get(actor.serverLevel()).cargo();if(book.order(orderId).isPresent())return;
        var expected=QUOTES.get(actor);if(expected==null||!request.hasUUID("QuoteToken")||!expected.token().equals(request.getUUID("QuoteToken"))||expected.expires()<actor.serverLevel().getGameTime())throw new IllegalArgumentException("delivery_quote_expired");
        var current=prepare(actor,request.getUUID("Selected"),purchase,request.getCompound("Values"));
        if(!expected.payer().equals(current.payer())||!Objects.equals(expected.offer(),current.offer())||!expected.source().equals(current.source())||!expected.destination().equals(current.destination())||!ItemStack.isSameItemSameComponents(expected.item(),current.item())||expected.quantity()!=current.quantity()||expected.goods()!=current.goods()||!expected.fees().equals(current.fees())||!expected.route().equals(current.route()))throw new IllegalArgumentException("delivery_quote_changed");
        book.reserve(orderId,expected.payer(),expected.seller(),orderId,expected.offer(),expected.quantity(),expected.goods(),expected.fees());
        try{configureDispatch(actor.getServer(),orderId,expected.route());if(expected.route().trip().getBoolean("Fleet"))EconomyManager.get(actor.serverLevel()).roadTolls().reserveTrip(orderId,expected.payer(),expected.route().trip().getLong("Tolls"),expected.route().trip());CargoShipmentRegistry.get(actor.getServer()).create(actor.getServer(),orderId,actor.getUUID(),expected.payer(),expected.source(),expected.destination(),expected.item(),expected.quantity(),expected.route());prepareDispatch(actor.getServer(),CargoShipmentRegistry.get(actor.getServer()).find(orderId).orElseThrow());}
        catch(RuntimeException invalid){book.refundUnattempted(orderId);EconomyManager.get(actor.serverLevel()).roadTolls().finishTrip(orderId);throw invalid;}
        QUOTES.remove(actor);
    }
    private static CompoundTag fleetQuote(ServerPlayer actor,Prepared p,CompoundTag values){var trip=p.route().trip();var t=new CompoundTag();t.putUUID("Token",p.token());t.putLong("Goods",p.goods());t.putLong("CarrierCost",trip.getLong("CarrierCost"));t.putLong("Tolls",trip.getLong("Tolls"));t.putLong("Transport",p.route().price());t.putLong("Total",Math.addExact(p.goods(),p.route().price()));t.putDouble("Distance",trip.getDouble("Distance"));t.putLong("EtaSeconds",trip.getLong("EtaSeconds"));t.putInt("Cycles",trip.getInt("Cycles"));t.putString("Source",p.source().name());t.putString("Destination",p.destination().name());t.putInt("Quantity",p.quantity());t.put("MapPreview",PublicFleetRegistry.map(actor.getServer(),trip));t.put("MapValues",values.copy());t.put("FrozenTrip",trip);t.putUUID("Train",trip.getUUID("Train"));t.putString("TrainName",PublicFleetRegistry.get(actor.getServer()).service(trip.getUUID("Train")).map(PublicFleetRegistry.Service::name).orElse(""));t.putString("CarrierName",OwnerRef.load(trip.getCompound("Carrier")).name(actor.getServer()));var routes=new ListTag();for(String phase:new TreeSet<>(trip.getCompound("Phases").getAllKeys())){var v=new CompoundTag();var phaseData=trip.getCompound("Phases").getCompound(phase);var path=RailRoutes.Path.load(phaseData.getCompound("Path"));var meter=RailRoutes.Path.load(phaseData.getCompound(phaseData.contains("MeterPath")?"MeterPath":"Path"));v.putString("Name",phase);v.putString("Phase",phase);v.putDouble("Distance",path.distance());v.putLong("Price",EconomyManager.get(actor.serverLevel()).roadTolls().estimate(meter.spans(),p.payer()));v.putString("Carrier",OwnerRef.load(trip.getCompound("Carrier")).name(actor.getServer()));routes.add(v);}t.put("Route",routes);var checks=new ListTag();for(String code:List.of("permissions","stock","receiver","rail","train","approach","return","funds")){var check=new CompoundTag();check.putString("Code",code);boolean funds=code.equals("funds")&&EconomyManager.get(actor.serverLevel()).accounts().balance(p.payer())<t.getLong("Total");check.putString("Status",funds?"BLOCKED":"READY");check.putString("MessageKey","gui.createcityexpansioncore.logistics.check."+code);check.putString("Detail",funds?Long.toString(t.getLong("Total")):"");checks.add(check);}if(trip.getBoolean("SearchLimited"))check(checks,"search_limited","WARNING","");if(trip.getBoolean("RegularEtaUnknown"))check(checks,"regular_eta_unknown","WARNING","");t.put("Checks",checks);return t;}
    private static CompoundTag blockedQuote(ServerPlayer actor,UUID selected,boolean purchase,CompoundTag values,String problem){
        var s=actor.getServer();var result=new CompoundTag();result.putString("Status","BLOCKED");var checks=new ListTag();result.put("Checks",checks);OwnerRef payer=null;boolean permission=false;CargoWarehouseRegistry.Warehouse source=null,destination=null;ItemStack item=ItemStack.EMPTY;int quantity=0;
        try{payer=CenterOperations.owner(values.getString("Owner"));permission=payer.canSpend(s,actor.getUUID());quantity=Math.toIntExact(CenterOperations.number(values,"Quantity"));if(purchase){var offer=EconomyManager.get(actor.serverLevel()).cargo().offer(selected).orElseThrow();permission&=CargoOwners.permits(s,OwnerRef.player(actor.getUUID()),CargoOwners.get(s).access("offer/"+offer.id(),offer.creator(),CargoTrainRegistry.AccessMode.PUBLIC));if(permission){source=CargoWarehouseRegistry.get(s).find(offer.warehouse()).orElse(null);item=ItemStack.parseOptional(s.registryAccess(),offer.item());}}else{var w=CargoWarehouseRegistry.get(s).find(selected).orElse(null);permission&=w!=null&&CargoWarehouseRegistry.permits(actor,w);if(permission){source=w;item=stockChoice(actor,w,values.getString("Stock"));}}}catch(RuntimeException unavailable){permission=false;}
        check(checks,"permissions",permission?"READY":"BLOCKED",permission?"":"delivery_payer_denied");
        try{var w=CargoWarehouseRegistry.get(s).find(CenterOperations.id(values,"Destination")).orElse(null);if(w!=null&&CargoWarehouseRegistry.access(s,w).owner().operates(s,actor.getUUID()))destination=w;}catch(RuntimeException ignored){}
        boolean stock=false;try{stock=permission&&source!=null&&!item.isEmpty()&&quantity>0&&quantity<=4096&&available(s,source,item)>=quantity;}catch(IllegalArgumentException unavailable){}
        check(checks,"stock",stock?"READY":"BLOCKED",permission?"delivery_stock_unavailable":"");boolean receiver=destination!=null&&CargoWarehouseRegistry.receivingInventory(s,destination)!=null;check(checks,"receiver",receiver?"READY":"BLOCKED","delivery_receiver_unavailable");
        boolean connected=false;if(permission&&source!=null&&destination!=null){for(UUID a:PublicFleetRegistry.stationsFor(s,source.point()))for(UUID b:PublicFleetRegistry.stationsFor(s,destination.point()))if(CargoRailConnections.path(s,a,b).isPresent())connected=true;result.putString("Source",source.name());result.putString("Destination",destination.name());}
        check(checks,"rail",connected?"READY":"BLOCKED","schedule_disconnected");boolean fleet=PublicFleetRegistry.get(s).services().stream().anyMatch(v->v.enabled()&&!PublicFleetRegistry.get(s).hasJob(v.train()));boolean line=CargoLineRegistry.get(s).all().stream().anyMatch(l->l.enabled()&&CargoOwners.permits(s,OwnerRef.player(actor.getUUID()),CargoLineRegistry.access(s,l)));check(checks,"train",fleet||line?"WARNING":"BLOCKED",problem);
        check(checks,"approach","WARNING",problem);check(checks,"return","WARNING",problem);check(checks,"funds","WARNING","delivery_quote_changed");return result;
    }
    private static void check(ListTag list,String code,String status,String detail){var t=new CompoundTag();t.putString("Code",code);t.putString("Status",status);t.putString("MessageKey","gui.createcityexpansioncore.logistics.check."+code);t.putString("Detail",detail);t.putString("ActionKey","gui.createcityexpansioncore.logistics.check.fix");list.add(t);}
    public static int available(MinecraftServer s,CargoWarehouseRegistry.Warehouse warehouse,ItemStack item){MasterCityTradeService.ensureSourceReady(s,warehouse);var ticker=CargoWarehouseRegistry.ticker(s,warehouse);if(ticker==null||!CargoWarehouseRegistry.nativeAuthorized(s,warehouse))return 0;long count=ticker.getAccurateSummary().getCountOf(item);for(var shipment:CargoShipmentRegistry.get(s).all())if(shipment.sourceWarehouse().equals(warehouse.id())&&ItemStack.isSameItemSameComponents(shipment.type(),item)&&shipment.stage()!=CargoShipmentRegistry.Stage.COMPLETED&&shipment.stage()!=CargoShipmentRegistry.Stage.CANCELLED){var order=EconomyManager.get(s.overworld()).cargo().order(shipment.id()).orElse(null);if(order!=null&&order.state()!=CargoCommerceBook.State.REFUNDED&&order.state()!=CargoCommerceBook.State.CANCELLED)count-=Math.max(0,shipment.quantity()-shipment.packaged());}return (int)Math.max(0,Math.min(Integer.MAX_VALUE,count));}
    private static List<CargoCommerceBook.Fee> fees(MinecraftServer s,CargoRoutePlanner.Route route){var fees=new ArrayList<CargoCommerceBook.Fee>();for(int i=0;i<route.legs().size();i++){var leg=route.legs().get(i);OwnerRef recipient=route.trip().getBoolean("Fleet")?OwnerRef.load(route.trip().getCompound("Carrier")):CargoLineRegistry.access(s,CargoLineRegistry.get(s).find(leg.line()).orElseThrow()).owner();fees.add(new CargoCommerceBook.Fee(leg.line(),i,recipient,leg.tariff()));}return List.copyOf(fees);}
    private static void prepareDispatch(MinecraftServer s,CargoShipmentRegistry.Shipment shipment){if(shipment.trip().getBoolean("Fleet"))PublicFleetRegistry.get(s).prepare(s,shipment);else CargoCharters.get(s).prepare(s,shipment);}
    private static void configureDispatch(MinecraftServer s,UUID order,CargoRoutePlanner.Route route){var phases=route.trip().getCompound("CarrierPhases");if(phases.isEmpty())return;var amounts=new LinkedHashMap<String,Long>();for(String phase:phases.getAllKeys())amounts.put(phase,phases.getLong(phase));EconomyManager.get(s.overworld()).cargo().configureCarrier(order,amounts);}
    /** Trusted server caller authorizes payer; all offer/native stock/receiver/dispatch constraints remain live. */
    public static UUID purchase(MinecraftServer s,UUID requestId,OwnerRef payer,UUID offerId,UUID destinationWarehouse,int quantity){
        return purchase(s,requestId,payer,offerId,destinationWarehouse,quantity,null);
    }
    public static UUID purchase(MinecraftServer s,UUID requestId,OwnerRef payer,UUID offerId,UUID destinationWarehouse,int quantity,CargoRoutePlanner.Route expectedRoute){
        var book=EconomyManager.get(s.overworld()).cargo();EconomyManager.get(s.overworld()).roadTolls().captureLegacy(book.orders());var old=book.order(requestId).orElse(null);if(old!=null){if(!old.payer().equals(payer)||!Objects.equals(old.offer(),offerId)||old.quantity()!=quantity)throw new IllegalArgumentException("Order identity conflict");return requestId;}
        var offer=book.offer(offerId).orElseThrow();var source=CargoWarehouseRegistry.get(s).find(offer.warehouse()).orElseThrow();var destination=CargoWarehouseRegistry.get(s).find(destinationWarehouse).orElseThrow();var item=ItemStack.parseOptional(s.registryAccess(),offer.item());
        if(!offer.active()||quantity<1||quantity>4096||quantity>offer.remaining()||item.isEmpty()||!offer.owner().equals(CargoWarehouseRegistry.access(s,source).owner())||!CargoOwners.permits(s,payer,CargoOwners.get(s).access("offer/"+offerId,offer.creator(),CargoTrainRegistry.AccessMode.PUBLIC))||CargoWarehouseRegistry.receivingInventory(s,destination)==null||available(s,source,item)<quantity)throw new IllegalArgumentException("delivery_stock_unavailable");
        var preference=expectedRoute!=null&&expectedRoute.trip().contains("Preference")?CargoRoutePlanner.Preference.valueOf(expectedRoute.trip().getString("Preference")):CargoRoutePlanner.Preference.CHEAPEST;
        var route=CargoRoutePlanner.plan(s,payer,source.point(),destination.point(),preference,"ANY",quantity,item).orElseThrow(()->new IllegalArgumentException("delivery_route_unavailable"));if(expectedRoute!=null&&!expectedRoute.equals(route))throw new IllegalArgumentException("delivery_quote_changed");long goods=Math.multiplyExact(quantity,offer.unitPrice());
        book.reserve(requestId,payer,offer.owner(),requestId,offerId,quantity,goods,fees(s,route));
        try{configureDispatch(s,requestId,route);if(route.trip().getBoolean("Fleet"))EconomyManager.get(s.overworld()).roadTolls().reserveTrip(requestId,payer,route.trip().getLong("Tolls"),route.trip());var shipment=CargoShipmentRegistry.get(s).create(s,requestId,offer.creator(),payer,source,destination,item,quantity,route);prepareDispatch(s,shipment);}
        catch(RuntimeException invalid){book.refundUnattempted(requestId);EconomyManager.get(s.overworld()).roadTolls().finishTrip(requestId);throw invalid;}return requestId;
    }
    public static CompoundTag routeQuote(ServerPlayer actor,OwnerRef payer,CargoWarehouseRegistry.Warehouse source,CargoWarehouseRegistry.Warehouse destination,ItemStack item,int quantity,long goods,CargoRoutePlanner.Route route){var prepared=new Prepared(UUID.randomUUID(),actor.serverLevel().getGameTime()+1200,payer,CargoWarehouseRegistry.access(actor.getServer(),source).owner(),null,source,destination,item,quantity,goods,route,fees(actor.getServer(),route));if(route.trip().getBoolean("Fleet"))return fleetQuote(actor,prepared,new CompoundTag());var result=new CompoundTag();result.putLong("Goods",goods);result.putLong("CarrierCost",route.price());result.putLong("Tolls",0);result.putLong("Transport",route.price());result.putLong("Total",Math.addExact(goods,route.price()));result.putString("Source",source.name());result.putString("Destination",destination.name());result.putInt("Quantity",quantity);var map=new CompoundTag();var values=new CompoundTag();values.putString("SourcePoint",source.point().toString());values.putString("DestinationPoint",destination.point().toString());values.putString("Preference","CHEAPEST");map.put("MapRoute",values);var points=new ListTag();for(UUID point:List.of(source.point(),destination.point())){var t=new CompoundTag();t.putString("Value",point.toString());points.add(t);}result.put("MapPreview",CargoMapView.snapshot(actor,map,points));result.put("Checks",new ListTag());return result;}
    public static void cancel(ServerPlayer actor,UUID shipmentId){
        var registry=CargoShipmentRegistry.get(actor.getServer());var shipment=registry.find(shipmentId).orElseThrow();
        var book=EconomyManager.get(actor.getServer().overworld()).cargo();var order=book.order(shipmentId).orElseThrow();
        boolean permitted=actor.hasPermissions(2)||order.payer().manages(actor.getServer(),actor.getUUID());
        if(!permitted)throw new IllegalArgumentException("shipment_cancel_denied");
        if(order.state()==CargoCommerceBook.State.CANCELLING){registry.requestCancellation(shipmentId);return;}
        if((order.state()==CargoCommerceBook.State.REFUNDED||order.state()==CargoCommerceBook.State.CANCELLED)&&shipment.stage()==CargoShipmentRegistry.Stage.CANCELLED)return;
        if(!shipment.canCancel(order,permitted))throw new IllegalArgumentException("shipment_not_cancellable");
        if(ShipmentCancellation.immediateRefund(order,shipment.stage(),shipment.packagingClaimed(),shipment.parcelCount())){
            if(!book.refundUnattempted(order.id()))throw new IllegalArgumentException("shipment_refund_unavailable");
            registry.cancelled(shipmentId);
        }else{
            if(!book.requestCancellation(order.id()))throw new IllegalArgumentException("shipment_not_cancellable");
            registry.requestCancellation(shipmentId);
        }
    }
    public static void publish(ServerPlayer actor,UUID warehouseId,CompoundTag values,UUID nonce){var warehouse=CargoWarehouseRegistry.get(actor.getServer()).find(warehouseId).orElseThrow();if(!CargoWarehouseRegistry.manages(actor,warehouse))throw new IllegalArgumentException("Warehouse management denied");var type=stockChoice(actor,warehouse,values.getString("Stock"));MasterCityTradeService.validateCitySale(actor.getServer(),warehouse,type,CenterOperations.number(values,"Price"));var book=EconomyManager.get(actor.serverLevel()).cargo();var offer=book.publish(nonce,actor.getUUID(),CargoWarehouseRegistry.access(actor.getServer(),warehouse).owner(),warehouseId,(CompoundTag)type.save(actor.registryAccess()),type.getHoverName().getString(),Math.toIntExact(CenterOperations.number(values,"Quantity")),CenterOperations.number(values,"Price"));var owner=CargoWarehouseRegistry.access(actor.getServer(),warehouse).owner();CargoOwners.get(actor.getServer()).change(actor.getServer(),actor.getUUID(),"offer/"+offer.id(),actor.getUUID(),CargoTrainRegistry.AccessMode.PUBLIC,new CargoOwners.Access(owner,CargoTrainRegistry.AccessMode.valueOf(values.getString("Access")),Set.of(),Set.of()));}
    private static ServerPlayer operator(MinecraftServer s,CargoWarehouseRegistry.Warehouse w){var ticker=CargoWarehouseRegistry.ticker(s,w);if(ticker==null)return null;return s.getPlayerList().getPlayers().stream().filter(p->CargoWarehouseRegistry.manages(p,w)&&ticker.behaviour.mayInteract(p)).findFirst().orElse(null);}
    @SubscribeEvent public static void tick(ServerTickEvent.Post event){var server=event.getServer();if(server.overworld().getGameTime()%20!=0)return;var registry=CargoShipmentRegistry.get(server);registry.reconcile(server);CargoCharters.get(server).tick(server);PublicFleetRegistry.get(server).tick(server);var book=EconomyManager.get(server.overworld()).cargo();int budget=4;
        for(var order:book.orders()){var shipment=registry.find(order.shipment()).orElse(null);if(shipment==null)continue;
            if((order.state()==CargoCommerceBook.State.HELD||order.state()==CargoCommerceBook.State.ATTEMPTED)&&shipment.stage()!=CargoShipmentRegistry.Stage.BLOCKED&&shipment.stage()!=CargoShipmentRegistry.Stage.CANCELLED){try{prepareDispatch(server,shipment);}catch(RuntimeException invalid){registry.blocked(shipment.id(),"charter_dispatch_blocked");continue;}}
            // Economy and physical metadata are separate SavedData files. Repair a completed
            // half-save without issuing another native request or repeating a credit.
            if(order.state()==CargoCommerceBook.State.CANCELLED){if(shipment.cancellationResolved()&&shipment.stage()!=CargoShipmentRegistry.Stage.CANCELLED)registry.cancellationCompleted(shipment.id());continue;}
            if(order.state()==CargoCommerceBook.State.REFUNDED){if(shipment.stage()==CargoShipmentRegistry.Stage.REQUESTED&&!shipment.packagingClaimed()&&shipment.parcelCount()==0)registry.cancelled(shipment.id());continue;}
            if(shipment.cancellationRequested()&&order.state()!=CargoCommerceBook.State.CANCELLING){book.requestCancellation(order.id());continue;}
            if(order.state()==CargoCommerceBook.State.CANCELLING){
                registry.requestCancellation(shipment.id());
                if(order.seller().available(server)&&order.fees().stream().allMatch(f->f.recipient().available(server))
                        &&(shipment.delivered()==0||shipment.receivingOwnerValid(server))&&shipment.cancellationResolved()
                        &&(!shipment.trip().getBoolean("Fleet")||PublicFleetRegistry.get(server).complete(shipment.id()))&&book.settleCancellation(order.id(),shipment.delivered(),shipment.recovered(),shipment::hopUnits))registry.cancellationCompleted(shipment.id());
                continue;
            }
            if(shipment.trip().getBoolean("Fleet")&&shipment.receivingOwnerValid(server)&&shipment.physicalComplete())book.settleGoods(order.id(),true);
            if(order.seller().available(server)&&order.fees().stream().allMatch(f->f.recipient().available(server))&&shipment.receivingOwnerValid(server)&&shipment.physicalComplete()&&(!shipment.trip().getBoolean("Fleet")||PublicFleetRegistry.get(server).complete(shipment.id()))&&book.settle(order.id(),true,shipment::hopComplete))registry.completed(shipment.id());
            if(order.state()!=CargoCommerceBook.State.HELD||budget<=0||shipment.stage()!=CargoShipmentRegistry.Stage.REQUESTED)continue;
            var warehouse=CargoWarehouseRegistry.get(server).find(shipment.sourceWarehouse()).orElse(null);if(warehouse==null)continue;var ticker=CargoWarehouseRegistry.ticker(server,warehouse);if(ticker==null||!CargoWarehouseRegistry.nativeAuthorized(server,warehouse))continue;
            if(!order.seller().equals(EconomyManager.get(server.overworld()).accounts().saleRecipient(order.offer(),CargoWarehouseRegistry.access(server,warehouse).owner()))||!shipment.receivingOwnerValid(server)){registry.blocked(shipment.id(),"Warehouse ownership changed before packaging");book.block(order.id(),"Ownership changed");continue;}
            try{MasterCityTradeService.ensureSourceReady(server,warehouse);}catch(IllegalArgumentException pending){registry.blocked(shipment.id(),pending.getMessage());book.block(order.id(),pending.getMessage());continue;}if(ticker.shipmentStock(server,warehouse.id(),shipment.id())<shipment.quantity())continue;
            if(!(shipment.trip().getBoolean("Fleet")?PublicFleetRegistry.get(server).prepared(server,shipment):CargoCharters.get(server).prepared(server,shipment)))continue;
            if(!book.markAttempted(order.id()))continue;budget--;
            try{var result=ticker.requestShipment(server,warehouse.id(),shipment.id());if(result!=CargoTickerBlockEntity.RequestResult.DISPATCH_ATTEMPTED){registry.blocked(shipment.id(),result.name());book.block(order.id(),result.name());}}
            catch(RuntimeException failed){registry.blocked(shipment.id(),"Create request interrupted; no automatic retry");book.block(order.id(),"Create request interrupted");}
        }
    }
}
